import{_ as d,o as a,c as e,a2 as o}from"./chunks/framework.Dh6DF7gt.js";const r="/ai-lab-smart-office/layout/office-layout-2d.svg",i="/ai-lab-smart-office/layout/office-layout-clean.png",b=JSON.parse('{"title":"办公室布局","description":"AI实验室办公室平面布局、功能分区和后续智能化点位规划基准。","frontmatter":{"title":"办公室布局","description":"AI实验室办公室平面布局、功能分区和后续智能化点位规划基准。"},"headers":[],"relativePath":"guide/office-layout.md","filePath":"guide/office-layout.md","lastUpdated":1785484427000}'),c={name:"guide/office-layout.md"};function l(f,t,s,h,n,u){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="办公室布局" tabindex="-1">办公室布局 <a class="header-anchor" href="#办公室布局" aria-label="Permalink to &quot;办公室布局&quot;">​</a></h1><h2 id="二维-cad-底图" tabindex="-1">二维 CAD 底图 <a class="header-anchor" href="#二维-cad-底图" aria-label="Permalink to &quot;二维 CAD 底图&quot;">​</a></h2><p><a href="/ai-lab-smart-office/layout/office-layout-2d.svg"><img src="'+r+'" alt="AI实验室办公室二维平面底图"></a></p><p>点击图片可查看矢量大图。二维底图采用毫米单位和独立图层，可以继续补充准确尺寸、弱电点位与智能化设备。</p><table tabindex="0"><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><a href="/ai-lab-smart-office/layout/office-layout-2d-cad.zip">CAD 下载包（ZIP）</a></td><td>推荐下载；解压后得到 DXF 源文件</td></tr><tr><td><a href="/ai-lab-smart-office/layout/office-layout-2d.dxf?v=c7d7df8">直接打开 DXF</a></td><td>使用 QCAD、LibreCAD、FreeCAD 或 AutoCAD 继续编辑</td></tr><tr><td><a href="/ai-lab-smart-office/layout/office-layout-2d.svg">SVG 矢量图</a></td><td>在线查看或用于后续网页点位图</td></tr><tr><td><a href="/ai-lab-smart-office/layout/office-layout-2d.pdf">PDF 打印版</a></td><td>评审、打印和现场标注</td></tr><tr><td><a href="/ai-lab-smart-office/layout/office-layout-2d.png">PNG 预览图</a></td><td>嵌入文档、Issue 或聊天记录</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">图纸使用边界</p><p>这是依据现场平面图照片转绘的初稿：总宽按图面 <code>20000 mm</code> 校准，总高暂按图面 <code>27200 mm</code> 转绘；内部尺寸、墙厚、柱位和门窗位置仍须现场复核。当前文件适合作为空间定位和方案讨论底图，不应直接作为拆改或结构施工依据。</p></div><h2 id="cad-图层" tabindex="-1">CAD 图层 <a class="header-anchor" href="#cad-图层" aria-label="Permalink to &quot;CAD 图层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图层</th><th>内容</th></tr></thead><tbody><tr><td><code>A-WALL</code> / <code>A-DOOR</code> / <code>A-WIND</code></td><td>墙体、门和窗</td></tr><tr><td><code>S-COLS</code></td><td>柱位</td></tr><tr><td><code>A-FURN</code> / <code>A-TEXT</code> / <code>A-DIMS</code></td><td>家具、文字和尺寸</td></tr><tr><td><code>E-NETWORK</code></td><td>网络、AP 与弱电点位（预留）</td></tr><tr><td><code>E-SECURITY</code></td><td>门禁与安防点位（预留）</td></tr><tr><td><code>E-SENSOR</code></td><td>环境与人体传感器点位（预留）</td></tr></tbody></table><p>CAD 文件由 <code>scripts/generate_office_floorplan.py</code> 生成；修改坐标或图层后，可重复生成 DXF、ZIP、SVG、PDF 和 PNG，确保各格式内容一致。</p><h2 id="打开-dxf-文件" tabindex="-1">打开 DXF 文件 <a class="header-anchor" href="#打开-dxf-文件" aria-label="Permalink to &quot;打开 DXF 文件&quot;">​</a></h2><ol><li>下载 <strong>CAD 下载包（ZIP）</strong> 并解压，得到 <code>office-layout-2d.dxf</code>。</li><li>使用 QCAD、LibreCAD、FreeCAD 或 AutoCAD，选择“文件 → 打开”并载入 DXF。</li><li>图纸单位选择 <strong>毫米（mm）</strong>；按需要显示或隐藏 <code>A-*</code>、<code>S-*</code>、<code>E-*</code> 图层。</li><li>如果只需要查看，不需要编辑，直接使用本页的 SVG 矢量图或 PDF 打印版即可。</li></ol><p>macOS 的“预览”通常不能直接显示 DXF；浏览器打开 DXF 时也可能只下载文件，而不会在线预览。</p><h2 id="原始平面图参考" tabindex="-1">原始平面图参考 <a class="header-anchor" href="#原始平面图参考" aria-label="Permalink to &quot;原始平面图参考&quot;">​</a></h2><p><a href="/ai-lab-smart-office/layout/office-layout-clean.png"><img src="'+i+'" alt="经清晰化处理的原始办公室平面图"></a></p><p>该版本保留原始房间、门向和尺寸标注，并完成裁切、灰度校正、对比度增强和锐化，供转绘核对与现场复测使用。</p><h2 id="功能分区" tabindex="-1">功能分区 <a class="header-anchor" href="#功能分区" aria-label="Permalink to &quot;功能分区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>主要空间</th><th>规划用途</th></tr></thead><tbody><tr><td>A 区</td><td>A大厅1、A大厅2、A大厅3</td><td>中部开放工位与主要协作区</td></tr><tr><td>A 区</td><td>A大厅4</td><td>独立交流、休息或小型接待区</td></tr><tr><td>B 区</td><td>B办公室1～3</td><td>东侧独立实验、研发或项目空间</td></tr><tr><td>C 区</td><td>C办公室1～5</td><td>西侧独立实验、研发或项目空间</td></tr><tr><td>D 区</td><td>D办公室1～3、D会议室</td><td>北侧项目空间与会议协作区</td></tr><tr><td>餐饮区</td><td>食堂、餐厅、灶台</td><td>用餐、茶歇与后勤保障</td></tr><tr><td>公共区</td><td>南侧前厅、前台、接待厅、走廊</td><td>访客接待、公共活动与通行</td></tr><tr><td>设施区</td><td>机房、厕所、电梯厅、入口</td><td>网络核心、基础设施与出入口</td></tr></tbody></table><p>图中的“办公室”和大厅编号暂作为房间定位代码使用；后续可根据 AI实验室的实际团队、设备和实验方向更新房间名称。</p><h2 id="智能化设计基准" tabindex="-1">智能化设计基准 <a class="header-anchor" href="#智能化设计基准" aria-label="Permalink to &quot;智能化设计基准&quot;">​</a></h2><p>后续专项图应统一以本页平面图为底图，并分层维护，避免在一张图上叠加过多信息：</p><ol><li><strong>网络与弱电层</strong>：机柜、交换机、AP、信息点、摄像头及线缆路径。</li><li><strong>照明与环境层</strong>：照明回路、人体存在、温湿度、空气质量与窗帘控制点。</li><li><strong>门禁与安防层</strong>：主要入口、机房、独立房间和公共区域的权限边界。</li><li><strong>设备与自动化层</strong>：控制面板、场景触发器、实验设备和能源计量点位。</li></ol><p>新增设备时，建议使用“分区—房间—设备类型—序号”的统一编号，例如 <code>C-03-AP-01</code>，并同步写入设备台账与验收记录。</p>',22)])])}const A=d(c,[["render",l]]);export{b as __pageData,A as default};
